using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class CheckForestRampRecovery {
 public static string Main(){var old=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;try{EditorSceneManager.OpenScene("Assets/Scenes/ForestLoopReverse.unity");Physics.SyncTransforms();var race=Object.FindAnyObjectByType<RaceDirector>();var car=race.vehicle;var reset=car.GetComponent<VehicleRespawn>();var flags=BindingFlags.NonPublic|BindingFlags.Instance;typeof(ArcadeVehicle).GetMethod("Awake",flags).Invoke(car,null);typeof(VehicleRespawn).GetMethod("Awake",flags).Invoke(reset,null);typeof(VehicleRespawn).GetField("race",flags).SetValue(reset,race);race.Racers.Clear();race.Racers.Add(new RacerState("ramp fixture",car,race.gates.Length-1,3));var layout=Object.FindAnyObjectByType<ForestLayout>();var unsafeJump=typeof(VehicleRespawn).GetMethod("UnsafeJump",flags);var rows=new System.Collections.Generic.List<string>();foreach(float offset in new[]{-15f,0f,15f}){var p=race.road.At(layout.jumpStarts[0]+offset,out _);rows.Add(((bool)unsafeJump.Invoke(reset,new object[]{p+Vector3.up*.5f})?"PASS ":"FAIL ")+"Existing Forest main jump approach/face excluded offset="+offset);}File.WriteAllLines("Docs/UndergroundPolish/forest-ramp-check.txt",rows);return string.Join("\n",rows);}finally{EditorSceneManager.OpenScene(old);}}
}
